 ComPtr<ID3D11Texture2D> texture;resource.As(&texture);D3D11_TEXTURE2D_DESC td{};texture->GetDesc(&td);td.Usage=D3D11_USAGE_STAGING;td.BindFlags=td.MiscFlags=0;td.CPUAccessFlags=D3D11_CPU_ACCESS_READ;ComPtr<ID3D11Texture2D> staging;hr=device->CreateTexture2D(&td,nullptr,&staging);if(FAILED(hr)){duplication->ReleaseFrame();return;}context->CopyResource(staging.Get(),texture.Get());D3D11_MAPPED_SUBRESOURCE mapped{};hr=context->Map(staging.Get(),0,D3D11_MAP_READ,0,&mapped);diagnostic<<"Map="<<hr<<"\n";if(SUCCEEDED(hr)){int w=bounds.right-bounds.left,h=bounds.bottom-bounds.top;BITMAPINFOHEADER bih{sizeof(BITMAPINFOHEADER),w,-h,1,32,BI_RGB};BITMAPFILEHEADER bfh{};bfh.bfType=0x4d42;bfh.bfOffBits=sizeof(bfh)+sizeof(bih);bfh.bfSize=bfh.bfOffBits+w*h*4;std::ofstream out(root/L"os-desktop-child.bmp",std::ios::binary);out.write((char*)&bfh,sizeof(bfh));out.write((char*)&bih,sizeof(bih));for(int y=0;y<h;++y)out.write((char*)mapped.pData+(y+bounds.top-desc.DesktopCoordinates.top)*mapped.RowPitch+(bounds.left-desc.DesktopCoordinates.left)*4,w*4);context->Unmap(staging.Get(),0);}duplication->ReleaseFrame();
